import {particleCourseAudio} from './particle-course-audio.js';
// Compare complete, natural sentences before interpreting a situation or filling a gap.
const example=(before,particle,after,meaning,scene)=>({text:before+particle+after,meaning,scene,focus:{start:before.length,end:before.length+particle.length},audio:particleCourseAudio(before+particle+after)});
const options=choices=>choices.map(([text,feedback])=>({text,feedback}));
const gap=(context,before,after,choices,answer,meaning)=>({kind:'particle',context,before,after,choices:options(choices),answer,text:before+choices[answer][0]+after,meaning,focus:{start:before.length,end:before.length+choices[answer][0].length},audio:particleCourseAudio(before+choices[answer][0]+after)});
const meaning=(context,row,choices,answer)=>({...row,kind:'meaning',context,choices:options(choices),answer});
const unit=(heading,examples,explanation,question,note)=>({heading,examples,explanation,question:typeof question==='function'?question(examples):question,...note?{note}:{}});
